const library=E.presets();
let state={groups:E.demo(),custom:[],settings:{team:1,cycle:30,lay:0}},undo=[],redo=[],mode='whole',selectedGroup=null,selectedBricks=new Set(),tool=null,pendingDims=[2,1,1],candidate=null,rotationPreview=null,renderIndex=[],savingTimer,toastTimer,lastPointer=null,altCamera=false;
