function validState(s){return !!s&&Array.isArray(s.groups)&&s.groups.length<=2000&&Array.isArray(s.custom)&&s.custom.length<=100&&s.settings&&Number.isFinite(s.settings.team)&&s.settings.team>=1&&Number.isFinite(s.settings.cycle)&&s.settings.cycle>=1&&Number.isFinite(s.settings.lay)&&s.settings.lay>=0&&[...s.groups,...s.custom].every(g=>g&&typeof g.id==='string'&&typeof g.name==='string'&&g.name.length<=120&&Array.isArray(g.bricks)&&g.bricks.length<=15000&&g.bricks.every(b=>b&&typeof b.id==='string'&&['full','half'].includes(b.kind)&&Array.isArray(b.c)&&b.c.length===3&&b.c.every(Number.isFinite)&&Array.isArray(b.d)&&b.d.length===3&&b.d.every(v=>v===1||v===2)&&b.d.reduce((a,v)=>a*v,1)===(b.kind==='half'?1:2)&&(!b.a||Number.isFinite(b.a)))&&(g.x===undefined||Number.isFinite(g.x))&&(g.z===undefined||Number.isFinite(g.z))&&(g.angle===undefined||Number.isFinite(g.angle)))&&s.groups.every(g=>Number.isFinite(g.x)&&Number.isFinite(g.z)&&Number.isFinite(g.angle))&&s.groups.reduce((n,g)=>n+g.bricks.length,0)<=20000}
