scene.add(new THREE.HemisphereLight(0xf4faff,0x9daebb,2.6));
const sun=new THREE.DirectionalLight(0xfffbf2,3);sun.position.set(-25,45,20);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-45,right:45,top:45,bottom:-45,near:.5,far:130});sun.shadow.bias=-.00025;sun.shadow.normalBias=.025;sun.shadow.radius=4;scene.add(sun);
