// A baked edge gradient and snow grain reveal joints while volumes touch exactly.
function snowTexture(){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');const data=ctx.createImageData(128,128);let seed=12345;for(let y=0;y<128;y++)for(let x=0;x<128;x++){seed=(seed*1664525+1013904223)>>>0;const edge=Math.min(x,y,127-x,127-y);const v=247-(edge<2?(2-edge)*14:0)+(seed%11)-5;const i=(y*128+x)*4;data.data[i]=v;data.data[i+1]=Math.min(255,v+2);data.data[i+2]=Math.min(255,v+3);data.data[i+3]=255}ctx.putImageData(data,0,0);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t}
