function worldMatrix(g,b){const w=E.worldBrick(g,b);dummy.position.fromArray(w.c);dummy.rotation.set(0,(g.angle+(b.a||0))*Math.PI/180,0);dummy.scale.fromArray(b.d);dummy.updateMatrix();return dummy.matrix}
function clearRoot(root){for(const m of [...root.children]){root.remove(m);if(m.material?.dispose)m.material.dispose();if(m.userData.disposeGeo)m.geometry.dispose()}}
function ghostBricks(g,bs,valid){clearRoot(ghostRoot);const mat=new THREE.MeshBasicMaterial({color:valid?0x41add1:0xe57166,transparent:true,opacity:.34,depthWrite:false});const instance=new THREE.InstancedMesh(geometry,mat,bs.length);bs.forEach((b,i)=>instance.setMatrixAt(i,worldMatrix(g,b)));instance.renderOrder=3;ghostRoot.add(instance)}
function rebuild(){if(bricksMesh){scene.remove(bricksMesh);bricksMesh.dispose()}renderIndex=E.allBricks(state.groups);bricksMesh=new THREE.InstancedMesh(geometry,material,Math.max(1,renderIndex.length));bricksMesh.count=renderIndex.length;bricksMesh.castShadow=true;bricksMesh.receiveShadow=true;const color=new THREE.Color();renderIndex.forEach(({g,b},i)=>{bricksMesh.setMatrixAt(i,worldMatrix(g,b));const v=.93+(i*31%17)/250;color.setRGB(v,v+.015,Math.min(1,v+.028));bricksMesh.setColorAt(i,color)});bricksMesh.instanceMatrix.needsUpdate=true;scene.add(bricksMesh);drawSelection()}
function drawSelection(){clearRoot(selectionRoot);const bs=mode==='whole'?renderIndex.filter(x=>x.g.id===selectedGroup):renderIndex.filter(x=>selectedBricks.has(x.b.id));if(!bs.length)return;const mat=new THREE.MeshBasicMaterial({color:0x278dbb,transparent:true,opacity:.18,depthWrite:false});const inst=new THREE.InstancedMesh(geometry,mat,bs.length);bs.forEach(({g,b},i)=>inst.setMatrixAt(i,worldMatrix(g,{...b,d:b.d.map(v=>v+.012)})));selectionRoot.add(inst);const box=new THREE.Box3();bs.forEach(({g,b})=>{const m=new THREE.Mesh(geometry);m.applyMatrix4(worldMatrix(g,b));box.expandByObject(m)});const outline=new THREE.Box3Helper(box,0x5fadc9);outline.userData.disposeGeo=true;selectionRoot.add(outline)}
function selected(){return state.groups.find(g=>g.id===selectedGroup)}
function chosenBrick(){const g=selected();return g?.bricks.find(b=>selectedBricks.has(b.id))}
function setMode(value){mode=value;selectedBricks.clear();cancelTool(false);update();drawSelection()}
function update(){const n=E.counts(state.groups,state.settings);for(const [key,value] of Object.entries({partsCount:n.parts,fullCount:n.full,halfCount:n.half,makeCount:n.make,teamCount:state.settings.team,timeCount:E.timeLabel(n.seconds)}))$(key).textContent=typeof value==='number'?value.toLocaleString('ru-RU'):value.replace(/(\d+) (ч|мин|сек)/g,'$1\u00a0$2');$('teamMinus').disabled=state.settings.team<=1;$('teamWord').textContent=`${state.settings.team===1?'человек':'чел.'} · ${state.settings.team} ${state.settings.team===1?'станочек':'станочков'}`;$('timeStage').textContent=state.settings.lay>0?'Изготовление и укладка':'Только изготовление';$('timeBreakdown').hidden=!state.settings.lay;$('timeBreakdown').textContent=`Изготовление: ${E.timeLabel(n.manufacture)} · Укладка: ${E.timeLabel(n.assembly)}`;$('cycleInput').value=state.settings.cycle;$('layInput').value=state.settings.lay;$('sceneCount').textContent=`Построек: ${state.groups.length} · Деталей: ${n.parts}`;$('undoBtn').disabled=!undo.length;$('redoBtn').disabled=!redo.length;$('wholeMode').classList.toggle('active',mode==='whole');$('brickMode').classList.toggle('active',mode==='brick');const g=selected(),b=chosenBrick();$('selectionPanel').hidden=!g||!!tool;$('groupTools').hidden=mode!=='whole';$('brickTools').hidden=mode!=='brick';$('rotationError').hidden=true;if(g){$('selectionType').textContent=mode==='whole'?'ВЫБРАННАЯ ПОСТРОЙКА':'ВЫБРАННЫЕ ДЕТАЛИ';$('selectionName').textContent=mode==='whole'?g.name:(selectedBricks.size>1?`Выбрано деталей: ${selectedBricks.size}`:b?.kind==='half'?'Половинка':'Целый кирпичик');$('selectionInfo').textContent=mode==='whole'?`${g.bricks.length} деталей · ${Math.round(g.angle*10)/10}°`:b?b.d.map(v=>v*120).join(' × ')+' мм':'';$('angleInput').value=g.angle}$('pendingRotation').hidden=tool?.type!=='brick';$('pendingDims').textContent=`Основание ${pendingDims[0]*120} × ${pendingDims[2]*120} мм · высота ${pendingDims[1]*120} мм`;$('fullBtn').classList.toggle('active',tool?.type==='brick'&&tool.kind==='full');$('halfBtn').classList.toggle('active',tool?.type==='brick'&&tool.kind==='half');view.classList.toggle('placing',!!tool);controls.enableRotate=!tool;controls.enablePan=true;document.querySelectorAll('.collection-card').forEach(el=>el.classList.toggle('active',tool?.template?.id===el.dataset.id))}
function hint(text,valid=true){$('actionHint').hidden=!text;$('hintText').textContent=text;$('actionHint').classList.toggle('invalid',!valid)}
function cancelTool(clearSelection=true){tool=null;candidate=null;rotationPreview=null;clearRoot(ghostRoot);hint('');if(clearSelection){selectedGroup=null;selectedBricks.clear()}update();drawSelection()}
function tab(which){$('collectionPanel').hidden=which!=='collection';$('bricksPanel').hidden=which!=='bricks';$('collectionTab').classList.toggle('active',which==='collection');$('bricksTab').classList.toggle('active',which==='bricks')}
function beginBrick(kind){document.querySelector('.left-panel').classList.remove('open');pendingDims=kind==='half'?[1,1,1]:[2,1,1];selectedBricks.clear();tool={type:'brick',kind};candidate=null;clearRoot(ghostRoot);mode='brick';update();hint('Наведите на грань или поставьте первый кирпичик на поле');drawSelection()}
function beginTemplate(t){document.querySelector('.left-panel').classList.remove('open');tool={type:'template',template:t,angle:0};candidate=null;clearRoot(ghostRoot);hint('Выберите место на поле · поворот: клавиша R');update()}
function thumb(canvas,template){const ctx=canvas.getContext('2d');canvas.width=228;canvas.height=210;ctx.clearRect(0,0,228,210);const boxes=template.bricks.map(b=>({c:b.c,d:b.d}));const project=p=>[(p[0]-p[2])*.866,(p[0]+p[2])*.36-p[1]*.95];let points=[];for(const b of boxes)for(const x of [-1,1])for(const y of [-1,1])for(const z of [-1,1])points.push(project(b.c.map((v,i)=>v+[x,y,z][i]*b.d[i]/2)));let minX=Math.min(...points.map(p=>p[0])),maxX=Math.max(...points.map(p=>p[0])),minY=Math.min(...points.map(p=>p[1])),maxY=Math.max(...points.map(p=>p[1]));const scale=Math.min(190/(maxX-minX),170/(maxY-minY));const pt=p=>{const v=project(p);return [114+(v[0]-(minX+maxX)/2)*scale,105+(v[1]-(minY+maxY)/2)*scale]};boxes.sort((a,b)=>(a.c[0]+a.c[2]+a.c[1]*.05)-(b.c[0]+b.c[2]+b.c[1]*.05));for(const b of boxes){const [x,y,z]=b.c,[dx,dy,dz]=b.d.map(v=>v/2);for(const [face,fill] of [[[[x-dx,y-dy,z+dz],[x+dx,y-dy,z+dz],[x+dx,y+dy,z+dz],[x-dx,y+dy,z+dz]],'#c5dae6'],[[[x+dx,y-dy,z-dz],[x+dx,y-dy,z+dz],[x+dx,y+dy,z+dz],[x+dx,y+dy,z-dz]],'#dceaf1'],[[[x-dx,y+dy,z-dz],[x+dx,y+dy,z-dz],[x+dx,y+dy,z+dz],[x-dx,y+dy,z+dz]],'#fafcfd']]){ctx.beginPath();face.forEach((p,i)=>{const q=pt(p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle='#a7c1d0';ctx.lineWidth=.6;ctx.stroke()}}}
function renderCollection(){$('collection').replaceChildren();for(const t of [...library,...state.custom]){const btn=document.createElement('button');btn.className='collection-card';btn.dataset.id=t.id;const canvas=document.createElement('canvas'),body=document.createElement('span'),name=document.createElement('b'),note=document.createElement('small'),count=document.createElement('small'),plus=document.createElement('span');name.textContent=t.name;note.textContent=t.note||'Ваша постройка';count.textContent=`${t.bricks.length} деталей · ${library.includes(t)?'с перевязкой':'свой образец'}`;plus.className='plus';plus.textContent='+';body.append(name,note,count);btn.append(canvas,body,plus);btn.onclick=()=>beginTemplate(t);$('collection').append(btn);thumb(canvas,t)}$('collectionCount').textContent=library.length+state.custom.length}
function setRay(event){const r=renderer.domElement.getBoundingClientRect();pointer.set((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera)}
