function placeCandidate(event){if(!tool||altCamera)return;lastPointer={clientX:event.clientX,clientY:event.clientY};setRay(event);candidate=null;if(tool.type==='brick'){const hit=hitBrick();let g,b;if(hit){g=hit.g;const normal=hit.hit.face.normal;const axis=Math.abs(normal.x)>.5?0:Math.abs(normal.y)>.5?1:2,sign=normal.getComponent(axis)>0?1:-1;const angle=hit.b.a||0,point=localPoint(g,hit.hit.point),tc=hit.b.c;const rp=E.turn(point[0],point[2],-angle),rc=E.turn(tc[0],tc[2],-angle);const pointFrame=[rp[0],point[1],rp[1]],targetFrame=[rc[0],tc[1],rc[1]];let center=pointFrame.map((v,i)=>{const origin=targetFrame[i]-hit.b.d[i]/2;return origin+Math.round(v-origin-pendingDims[i]/2)+pendingDims[i]/2});center[axis]=targetFrame[axis]+sign*(hit.b.d[axis]+pendingDims[axis])/2;if(axis===1&&sign>0){const length=pendingDims[0]===2?0:pendingDims[2]===2?2:-1;if(length>=0&&hit.b.d[length]===2){const edge=targetFrame[length]-hit.b.d[length]/2;center[length]=edge+Math.round((pointFrame[length]-edge)/2)*2}}if(axis!==1)center[1]=Math.max(pendingDims[1]/2,center[1]);const c=E.turn(center[0],center[2],angle);b={id:E.uid(),kind:tool.kind,c:[c[0],center[1],c[1]],d:[...pendingDims],a:angle};const wb=E.worldBrick(g,b);if(!E.contact(wb,hit.w)){candidate={ok:false,reason:'Нужно соприкосновение граней, а не ребра или угла',g,b};ghostBricks(g,[b],false);hint(candidate.reason,false);return}}else{const p=groundPoint();if(!p)return;g={id:E.uid(),name:'Ручная постройка',x:0,z:0,angle:0,bricks:[]};b={id:E.uid(),kind:tool.kind,c:[Math.round(p.x-pendingDims[0]/2)+pendingDims[0]/2,pendingDims[1]/2,Math.round(p.z-pendingDims[2]/2)+pendingDims[2]/2],d:[...pendingDims],a:0}}if(!hit){const world=E.worldBrick(g,b),attached=E.allBricks(state.groups).find(x=>E.contact(world,x.w));if(attached){const old=g;g=attached.g;const q=E.turn(b.c[0]-g.x,b.c[2]-g.z,-g.angle);b={...b,c:[q[0],b.c[1],q[1]],a:-g.angle}}}const result=E.validateBrick(state.groups,g,b);candidate={...result,g,b};ghostBricks(g,[b],result.ok);hint(result.ok?`${hit?'Стыковка граней · 0 мм зазора':'На поле · новая постройка'} · щёлкните для установки`:result.reason,result.ok)}else{const p=groundPoint();if(!p)return;let g;if(tool.type==='template')g=E.instantiate(tool.template,Math.round(p.x),Math.round(p.z),tool.angle);else g={...E.clone(tool.original),x:Math.round(p.x*2)/2,z:Math.round(p.z*2)/2};const snap=E.snapGroup(state.groups,g,tool.type==='move'?g.id:null);g=snap.group;const result=E.validateGroup(state.groups,g,tool.type==='move'?g.id:null);candidate={...result,g};ghostBricks(g,g.bricks,result.ok);hint(result.ok?(snap.snapped?'Точная стыковка секций · 0 мм зазора':'Щёлкните для установки · R — поворот на 90°'):result.reason,result.ok)}}
function commitCandidate(){if(!candidate)return;if(!candidate.ok){toast(candidate.reason);return}const c=candidate,type=tool.type;if(type==='brick'){mutate(()=>{let group=state.groups.find(g=>g.id===c.g.id);if(!group){group=c.g;state.groups.push(group)}group.bricks.push(c.b);selectedGroup=group.id});candidate=null;clearRoot(ghostRoot);hint('Кирпичик установлен · продолжайте кладку')}else{mutate(()=>{if(type==='move'){state.groups=state.groups.map(g=>g.id===c.g.id?c.g:g)}else state.groups.push(c.g);selectedGroup=c.g.id});tool=null;candidate=null;clearRoot(ghostRoot);hint('');update();drawSelection()}}
let pointerDown=null;
renderer.domElement.addEventListener('pointerdown',event=>{pointerDown={x:event.clientX,y:event.clientY,button:event.button};if(event.altKey){altCamera=true;controls.enableRotate=true}if(event.pointerType==='touch'&&tool)placeCandidate(event)});
renderer.domElement.addEventListener('pointermove',event=>{if(tool)placeCandidate(event)});
renderer.domElement.addEventListener('pointerleave',()=>{if(tool){clearRoot(ghostRoot);candidate=null}});
renderer.domElement.addEventListener('pointerup',event=>{const down=pointerDown;pointerDown=null;const wasAlt=altCamera;altCamera=false;controls.enableRotate=!tool;if(!down||down.button!==0||wasAlt||Math.hypot(event.clientX-down.x,event.clientY-down.y)>5)return;if(tool){placeCandidate(event);commitCandidate();return}setRay(event);const hit=hitBrick();rotationPreview=null;clearRoot(ghostRoot);if(!hit){if(!event.shiftKey){selectedGroup=null;selectedBricks.clear()}}else{if(!event.shiftKey||mode==='whole')selectedBricks.clear();selectedGroup=hit.g.id;if(mode==='brick'){if(selectedBricks.has(hit.b.id))selectedBricks.delete(hit.b.id);else selectedBricks.add(hit.b.id)}}update();drawSelection()});
function previewBrickRotation(axis,apply=false){if(tool?.type==='brick'){const temporary={c:pendingDims.map(v=>v/2),d:pendingDims,kind:tool.kind};const next=E.rotateBrick(temporary,axis);if(apply){pendingDims=next.d;update();if(lastPointer)placeCandidate(lastPointer)}else{const old=pendingDims;pendingDims=next.d;if(lastPointer)placeCandidate(lastPointer);pendingDims=old}return}const g=selected(),b=chosenBrick();if(!g||!b||selectedBricks.size!==1){if(apply)toast('Выберите один кирпичик для поворота');return}const next=E.rotateBrick(b,axis),result=E.validateBrick(state.groups,g,next,b.id);ghostBricks(g,[next],result.ok);rotationPreview={g,b:next,...result};$('rotationError').hidden=result.ok;$('rotationError').textContent=result.reason;if(apply){if(!result.ok){toast(result.reason);return}mutate(()=>{g.bricks=g.bricks.map(old=>old.id===b.id?next:old)});clearRoot(ghostRoot)}}
const rotations=[['↶ Влево','y'],['↷ Вправо','y'],['↟ Вперёд','x'],['↡ Назад','x'],['↰ На левый бок','z'],['↱ На правый бок','z']];
document.querySelectorAll('[data-rotation]').forEach(el=>rotations.forEach(([label,axis])=>{const btn=document.createElement('button');btn.textContent=label+' 90°';btn.dataset.axis=axis;btn.onclick=()=>previewBrickRotation(axis,true);btn.onpointerenter=()=>previewBrickRotation(axis);btn.onpointerleave=()=>{if(rotationPreview?.ok===false)return;rotationPreview=null;clearRoot(ghostRoot);if(tool&&lastPointer)placeCandidate(lastPointer)};el.append(btn)}));
function groupRotation(angle,apply=false){const g=selected();if(!g)return;const next={...g,angle:((Number(angle)%360)+360)%360},result=E.validateGroup(state.groups,next,g.id);ghostBricks(next,next.bricks,result.ok);$('rotationError').hidden=result.ok;$('rotationError').textContent=result.reason;if(apply){if(!result.ok){toast(result.reason);return}mutate(()=>g.angle=next.angle);clearRoot(ghostRoot)}}
function history(direction){const src=direction==='undo'?undo:redo,dest=direction==='undo'?redo:undo;if(!src.length)return;dest.push(E.clone(state));state=src.pop();cancelTool();renderCollection();rebuild();update();persist()}
function removeSelected(){const g=selected();if(!g)return;mutate(()=>{if(mode==='whole')state.groups=state.groups.filter(x=>x.id!==g.id);else{state.groups.forEach(x=>x.bricks=x.bricks.filter(b=>!selectedBricks.has(b.id)));state.groups=state.groups.filter(x=>x.bricks.length)}selectedGroup=null;selectedBricks.clear()});clearRoot(ghostRoot)}
function fit(){const bs=E.allBricks(state.groups);if(!bs.length){controls.target.set(0,0,0);camera.position.set(18,20,24);controls.update();return}const bounds=new THREE.Box3();bs.forEach(({w})=>bounds.expandByPoint(new THREE.Vector3(...w.c)));const center=bounds.getCenter(new THREE.Vector3());const size=bounds.getSize(new THREE.Vector3());const extent=Math.max(size.x,size.z,12);const distance=extent/(2*Math.tan(camera.fov*Math.PI/360))*1.5;controls.target.copy(center);camera.position.copy(controls.target).add(new THREE.Vector3(.8,.8,1).normalize().multiplyScalar(distance+10));controls.update()}
function team(delta){mutate(()=>state.settings.team=Math.max(1,Math.min(999,state.settings.team+delta)))}
$('teamMinus').onclick=()=>team(-1);$('teamPlus').onclick=()=>team(1);
for(const [id,key,min] of [['cycleInput','cycle',1],['layInput','lay',0]])$(id).onchange=()=>{const value=Math.min(86400,Math.max(min,Math.round(Number($(id).value)||min)));mutate(()=>state.settings[key]=value)};
$('mobileWorkshop').onclick=()=>document.querySelector('.left-panel').classList.toggle('open');$('statsToggle').onclick=()=>document.querySelector('.stats-panel').classList.toggle('expanded');$('collectionTab').onclick=()=>tab('collection');$('bricksTab').onclick=()=>tab('bricks');$('fullBtn').onclick=()=>beginBrick('full');$('halfBtn').onclick=()=>beginBrick('half');$('wholeMode').onclick=()=>setMode('whole');$('brickMode').onclick=()=>setMode('brick');$('cancelTool').onclick=()=>cancelTool(false);$('deselectBtn').onclick=()=>cancelTool();$('deleteBtn').onclick=removeSelected;$('undoBtn').onclick=()=>history('undo');$('redoBtn').onclick=()=>history('redo');
$('moveBtn').onclick=()=>{const g=selected();if(g){tool={type:'move',original:E.clone(g)};update();hint('Выберите новое место · R — поворот на 90°')}};
$('duplicateBtn').onclick=()=>{const g=selected();if(g)beginTemplate({name:g.name,bricks:E.clone(g.bricks),id:'copy',angle:g.angle});if(tool)tool.angle=g.angle};
$('groupRotate90').onclick=()=>groupRotation(selected().angle+90,true);$('angleInput').oninput=()=>groupRotation($('angleInput').value);$('angleApply').onclick=()=>groupRotation($('angleInput').value,true);
$('selectGroupBricks').onclick=()=>{const g=selected();if(g){g.bricks.forEach(b=>selectedBricks.add(b.id));update();drawSelection()}};
$('newBtn').onclick=()=>{mutate(()=>state.groups=[]);cancelTool();fit();toast('Чистое поле. Предыдущее действие можно отменить.')};$('demoBtn').onclick=()=>{mutate(()=>state.groups=E.demo());cancelTool();fit()};
$('orbitBtn').onclick=()=>{controls.mouseButtons.LEFT=THREE.MOUSE.ROTATE;$('orbitBtn').classList.add('active');$('panBtn').classList.remove('active')};$('panBtn').onclick=()=>{controls.mouseButtons.LEFT=THREE.MOUSE.PAN;$('panBtn').classList.add('active');$('orbitBtn').classList.remove('active')};
$('topBtn').onclick=()=>{const distance=camera.position.distanceTo(controls.target);camera.position.copy(controls.target).add(new THREE.Vector3(0,distance,.0001));controls.update();$('topBtn').classList.add('active')};$('perspectiveBtn').onclick=()=>{const d=camera.position.distanceTo(controls.target);camera.position.copy(controls.target).add(new THREE.Vector3(.8,.85,1).normalize().multiplyScalar(d));controls.update();$('topBtn').classList.remove('active')};
$('zoomIn').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(.8).add(controls.target);controls.update()};$('zoomOut').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(1.2).add(controls.target);controls.update()};$('fitBtn').onclick=fit;
$('helpBtn').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('startBtn').onclick=()=>$('helpDialog').close();
let savedBricks=[];
$('saveCollectionBtn').onclick=()=>{const g=selected();const items=E.allBricks(state.groups).filter(x=>mode==='whole'?x.g.id===g?.id:selectedBricks.has(x.b.id));if(!items.length){toast('Сначала выберите постройку или выделите кирпичики с Shift');return}const base=items[0].g;const points=items.map(({g,b,w})=>{const q=E.turn(w.c[0],w.c[2],-base.angle);return {...E.clone(b),id:E.uid(),c:[q[0],w.c[1],q[1]],a:g.angle+(b.a||0)-base.angle}});const minY=Math.min(...points.map(b=>b.c[1]-b.d[1]/2));points.forEach(b=>b.c[1]-=minY);savedBricks=E.centered(points);$('templateName').value=g?.name==='Ручная постройка'?'':g?.name||'';$('savePartsInfo').textContent=`Деталей в образце: ${items.length}. Исходная постройка останется на поле.`;$('nameDialog').showModal();$('templateName').focus()};
$('nameDialog').addEventListener('close',()=>{if($('nameDialog').returnValue==='save'&&$('templateName').value.trim()){mutate(()=>state.custom.push({id:E.uid(),name:$('templateName').value.trim(),note:'Ваша постройка',bricks:E.clone(savedBricks)}));renderCollection();tab('collection');toast('Постройка добавлена в вашу коллекцию')}});
$('exportBtn').onclick=()=>{const data=new Blob([JSON.stringify({...state,format:'snegostroy',version:1},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(data);a.download='snegostroy-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('importFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>15e6)throw Error();const data=JSON.parse(await file.text());if(!validState(data))throw Error();mutate(()=>state={groups:data.groups,custom:data.custom,settings:data.settings});cancelTool();renderCollection();fit();toast('Проект открыт')}catch{toast('Не удалось открыть проект: проверьте формат файла')}event.target.value=''};
window.addEventListener('keydown',event=>{if(event.target.matches('input,textarea')||document.querySelector('dialog[open]'))return;if(event.key==='Escape'){cancelTool();return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();history(event.shiftKey?'redo':'undo')}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();history('redo')}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();removeSelected()}if(event.key.toLowerCase()==='r'){if(tool?.type==='brick')previewBrickRotation('y',true);else if(tool){if(tool.type==='move')tool.original.angle+=90;else tool.angle+=90;if(lastPointer)placeCandidate(lastPointer)}else if(selected())groupRotation(selected().angle+90,true)}});
window.addEventListener('beforeunload',()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}});
const resize=()=>{const w=view.clientWidth,h=view.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.setViewOffset(w,h,w>700?130:55,0,w,h);camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(view);
renderCollection();rebuild();update();resize();fit();
function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)}animate();
// A read-only geometry adapter also makes browser QA use real raycasting and UI input.
window.snegostroy={getState:()=>E.clone(state),getCamera:()=>({position:camera.position.toArray(),target:controls.target.toArray()}),projectPoint:(x,y,z)=>{const p=new THREE.Vector3(x,y,z).project(camera),r=renderer.domElement.getBoundingClientRect();return {x:r.left+(p.x+1)*r.width/2,y:r.top+(1-p.y)*r.height/2}},hitAt:(x,y)=>{setRay({clientX:x,clientY:y});const h=hitBrick();return h?{group:h.g.id,brick:h.b.id,point:h.hit.point.toArray(),normal:h.hit.face.normal.toArray()}:null},getCandidate:()=>candidate?E.clone(candidate):null};
